    Object.values(window.FR || {}).forEach((o) => Object.values(o).forEach(grab)); Object.values(window.BG || {}).forEach(grab);
    Object.values(window.TOYS || {}).forEach((t) => urls.add('img3d/' + t[0] + '?v=' + (window.TOY_V || 't1')));
